insert into qna_questions (legacy_ts, category, title, content, tags, anonymous, created_at) values
('seed-q01','세무','관계회사 대여금, 업무무관 가지급금으로 보는 기준이 어디까지인가요?','거래처가 아닌 관계회사(지분 40%)에 운영자금을 대여했습니다. 이자율은 가중평균차입이자율로 받고 있는데, 세무조사에서 업무무관 가지급금으로 볼 여지가 있는지 궁금합니다. 인정이자 계산이나 지급이자 손금불산입까지 걸리는 기준선이 실무적으로 어디쯤인지, 소명 자료는 어디까지 준비해 두시는지 의견 부탁드립니다.','가지급금,특수관계자',true,'2026-07-27T09:10:00Z'),
('seed-q02','실무','거래처 신용등급이 두 단계 떨어졌는데 여신 한도 어떻게 조정하세요?','주 거래처 등급이 갑자기 하락했습니다. 한도 축소 기준과 통보 방식 다들 어떻게 하시는지 궁금합니다.','여신,신용등급',false,'2026-07-27T14:30:00Z'),
('seed-q03','세무','가업승계 증여세 특례, 사후관리 요건 실무 경험 있으신 분?','5년 사후관리 중 고용유지 요건을 못 맞출 것 같은데 추징 규모가 어느 정도인지 궁금합니다.','가업승계,증여세',false,'2026-07-28T10:00:00Z'),
('seed-q04','회계','리스 회계처리, 사용권자산 감가 기준 다들 어떻게 잡으세요?','리스기간과 내용연수가 다를 때 상각 기준을 어디에 맞추는지 실무 사례가 필요합니다.','리스,사용권자산',true,'2026-07-28T11:20:00Z'),
('seed-q05','법령','중대재해처벌법 적용 사업장, 재무·관리팀이 챙길 항목이 있을까요?','안전관리 예산 편성과 증빙 관리 측면에서 재무팀이 준비할 게 있는지 궁금합니다.','중대재해,컴플라이언스',false,'2026-07-28T16:40:00Z'),
('seed-q06','실무','결산 마감 일정 관리, 부서별 체크리스트 템플릿 공유 가능하신 분?','분기 결산마다 부서 취합이 늦어집니다. 쓰시는 체크리스트나 캘린더 공유 부탁드려요.','결산,템플릿',false,'2026-07-29T00:30:00Z'),
('seed-q07','세무','외화환산손익 인식 시점, 결산일 기준 환율 적용이 맞나요?','외화예금과 외화매출채권 환산 시점을 결산일 매매기준율로 잡는 게 맞는지 확인 부탁드립니다.','외화환산,결산',true,'2026-07-29T01:00:00Z'),
('seed-q08','경영','런웨이 12개월 남은 시점, 재무팀이 먼저 손대야 할 항목의 우선순위는?','비용 구조를 다시 짜야 하는데 어디부터 손대는 게 효과적이었는지 경험 나눠주세요.','런웨이,비용관리',false,'2026-07-26T09:00:00Z'),
('seed-q09','회계','개발비 자산화 요건, 내부 프로젝트에서 어디까지 인정받으셨나요?','무형자산 인식 기준 중 기술적 실현가능성을 어떤 문서로 입증해 남기시는지 궁금합니다.','개발비,무형자산',false,'2026-07-28T13:00:00Z'),
('seed-q10','법령','주 52시간 유연근무 도입, 급여 설계에서 놓치기 쉬운 지점은?','선택근로제 정산기간 설정과 연장수당 계산에서 실수했던 사례 공유 부탁드립니다.','주52시간,급여',true,'2026-07-26T15:00:00Z')
on conflict (legacy_ts) do nothing;

insert into qna_answers (question_ts, author, official, content, created_at) values
-- q01 가지급금 (답변 2)
('seed-q01','크레디뷰 리서치',true,'업무무관 가지급금 판단의 핵심은 ''대여의 업무 관련성''입니다. 관계회사라는 사실만으로 곧바로 업무무관이 되지는 않지만, ① 대여의 사업상 필요성 ② 적정 이자의 수취 ③ 회수 계획의 구체성이 소명되지 않으면 세무상 업무무관으로 재구성될 수 있습니다.

가중평균차입이자율 이상으로 이자를 받고 계시다면 인정이자 이슈는 크지 않습니다. 다만 대여 규모가 자기자본 대비 과도하거나 회수가 장기 지연되면 지급이자 손금불산입 대상이 될 수 있으니, 이사회 결의서·금전소비대차 약정서·회수 이력을 함께 갖춰 두시길 권합니다.','2026-07-27T10:00:00Z'),
('seed-q01','익명',false,'실무에서는 ''왜 이 시점에, 왜 이 회사에 빌려줬는가''에 대한 사업상 이유를 문서로 남기는 게 가장 중요합니다. 이자율만 맞춰 두고 근거 서류가 없으면 조사에서 방어가 어렵습니다.','2026-07-27T11:30:00Z'),
-- q02 여신 한도 (답변 1)
('seed-q02','익명',false,'저희는 내부 여신규정에 등급별 한도표를 두고, 2단계 이상 하락 시 즉시 재심사 대상으로 올립니다. 실무 순서는 ① 신규 여신(추가 외상) 중단 ② 기존 한도는 회수 일정에 맞춰 단계적 축소 ③ 필요 시 담보·보증 보강 요구 순이고, 축소 통보는 분쟁 예방을 위해 반드시 서면(이메일 포함)으로 남깁니다. 급격한 일괄 축소는 거래처 연쇄 부실을 부를 수 있어 회수 계획과 함께 조정하는 편입니다.','2026-07-27T16:00:00Z'),
-- q03 가업승계 (답변 1 · 운영사)
('seed-q03','크레디뷰 리서치',true,'먼저 제도 구분이 필요합니다. ''가업승계 증여세 과세특례''(조세특례제한법 §30의6)의 사후관리는 5년이며, 핵심 요건은 수증자의 가업 종사·대표이사 취임과 지분 유지입니다. 걱정하시는 고용유지 요건(정규직 근로자 수 또는 총급여 90% 이상 유지)은 상속 단계의 ''가업상속공제''(상증세법 §18의2) 사후관리 요건입니다.

어느 쪽이든 사후관리 요건을 위반하면 공제·특례받은 세액을 추징하면서 이자상당액이 가산되므로 위반 기간이 길수록 부담이 커집니다. 연도별 고용·지분·업종 유지 현황을 매년 점검표로 남겨 두시고, 요건 미달이 예상되면 사전에 세무대리인과 구제 가능성(업종 변경 승인 등)을 검토하시길 권합니다.','2026-07-28T11:00:00Z'),
-- q04 리스 (답변 1 · 운영사)
('seed-q04','크레디뷰 리서치',true,'K-IFRS 제1116호 기준으로는 ① 리스 종료 시 소유권이 이전되거나 매수선택권 행사가 상당히 확실한 경우 → 기초자산의 내용연수로 상각하고, ② 그 외에는 리스기간과 내용연수 중 짧은 기간으로 상각합니다. 실무에서는 갱신선택권을 리스기간에 포함할지가 쟁점이 되는 경우가 많으니, 갱신 가능성 판단 근거(과거 갱신 이력·이전 비용 등)를 문서로 남겨 두세요. 일반기업회계기준을 쓰는 회사라면 운용리스는 자산 인식 없이 비용 처리라 이 쟁점 자체가 발생하지 않습니다.','2026-07-28T13:00:00Z'),
-- q05 중대재해 — 답변 없음 (첫 답변을 기다리는 상태 유지)
-- q06 결산 체크리스트 (답변 1)
('seed-q06','익명',false,'부서 취합 지연은 체크리스트보다 ''컷오프 규칙''이 해결해 줬습니다. 증빙 제출 마감(D-3), 미제출 항목은 가마감 후 익월 반영 원칙을 공지하고, 부서별 담당자·마감 항목·기한을 한 장에 정리한 캘린더를 매월 초에 배포합니다. 블랙북 자료실에 결산 마감 체크리스트 서식이 올라와 있으니 참고하셔도 좋겠습니다.','2026-07-29T02:00:00Z'),
-- q07 외화환산 (답변 1)
('seed-q07','익명',false,'네, 맞습니다. 외화예금·외화매출채권 같은 화폐성 항목은 보고기간 말(결산일)의 마감환율로 환산하고, 환산 차이는 당기손익으로 인식합니다. 실무에서는 서울외국환중개 매매기준율을 쓰는 것이 일반적입니다. 다만 재고자산처럼 비화폐성 항목은 거래일 환율을 유지한다는 점만 구분하시면 됩니다.','2026-07-29T02:30:00Z'),
-- q08 런웨이 (답변 1 · 운영사)
('seed-q08','크레디뷰 리서치',true,'경험상 순서가 중요합니다. ① 13주 롤링 현금흐름 예측부터 만들어 ''언제 얼마가 부족한지''를 주 단위로 보이게 하고, ② 계약성 고정비(임차료·구독·외주)를 재협상 대상으로 먼저 올립니다. ③ 매출채권 회수기간 단축과 재고 축소로 운전자본에서 현금을 회수하고, ④ 인건비는 채용 동결 → 변동급 조정 순으로 마지막에 다룹니다. 동시에 ⑤ 정책자금·보증부 대출 등 유동성 보강을 병행하면 런웨이 12개월은 통상 6개월 이상 연장할 여지가 있습니다.','2026-07-26T10:30:00Z'),
-- q09 개발비 (답변 1)
('seed-q09','익명',false,'감사인이 가장 먼저 보는 건 ''자산화 개시 시점''의 근거입니다. 저희는 기획 단계와 개발 단계를 구분하는 내부 품의(개발계획서 승인)를 자산화 개시점으로 잡고, 이후 단계별 산출물·테스트 결과·사업화 계획(시장성 검토)을 프로젝트 폴더에 남깁니다. K-IFRS 제1038호의 6가지 요건을 항목별로 매핑한 체크시트를 만들어 두면 감사 대응이 훨씬 수월합니다.','2026-07-28T15:00:00Z'),
-- q10 주52시간 (답변 1 · 운영사)
('seed-q10','크레디뷰 리서치',true,'선택근로제에서 가장 많이 놓치는 지점은 두 가지입니다. ① 정산기간은 원칙 1개월 이내(연구개발 업무는 최대 3개월)인데, 이를 넘겨 설계하면 제도 자체가 무효가 될 수 있습니다. ② 연장수당은 ''주 단위''가 아니라 정산기간 전체의 평균 주 40시간 초과분으로 계산해야 하는데, 매주 따로 계산해 과소·과다 지급하는 실수가 잦습니다. 근로자대표 서면합의서에 정산기간·대상 업무·표준근로시간을 명확히 적어 두는 것이 분쟁 예방의 출발점입니다.','2026-07-26T17:00:00Z');
